effect.shader:
void main() {
    vec2 offset = (acScreenNorm - center) * vec2(acAspect, 1.0);
    float dist = length(offset);

    float falloff = 1.0 - smoothstep(0.0, max(radius, 0.001), dist);
    float angle = atan(offset.y, offset.x) + radians(twist) * falloff;

    vec2 warped = vec2(cos(angle), sin(angle)) * dist;
    vec2 sampleUv = warped / vec2(acAspect, 1.0) + center;

    fragColor = texture(inputImg, clamp(sampleUv, 0.0, 1.0));
}
